'use strict';

// MODULES //

var isBooleanArray = require( '@stdlib/assert/is-booleanarray' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var hasProperty = require( '@stdlib/assert/has-property' );
var hasOwn = require( '@stdlib/assert/has-own-property' );
var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var ndims = require( '@stdlib/ndarray/base/ndims' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var getDType = require( '@stdlib/ndarray/base/dtype' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );


// MAIN //

/**
* Returns whether the ndarrays can use the typed native interface.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {boolean} whether the ndarrays can use the native interface
*/
function canUseNative( arrays ) {
	var stride;
	var offset;
	var last;
	var data;
	var arr;
	var N;
	var i;

	N = numelDimension( arrays[ 0 ], 0 );
	if ( !isSafeInteger( N ) || N <= 0 ) {
		return false;
	}
	for ( i = 0; i < 4; i++ ) {
		arr = arrays[ i ];

		// Custom serialization hooks are not part of the JavaScript interface.
		if ( hasProperty( arr, '__array_meta_dataview__' ) && ( !( arr instanceof ndarray ) || hasOwn( arr, '__array_meta_dataview__' ) ) ) {
			return false;
		}
		if ( ndims( arr ) !== 1 || typeof arr.strides !== 'object' || arr.strides === null ) {
			return false;
		}
		if ( !isSafeInteger( arr.shape[ 0 ] ) || arr.shape[ 0 ] < 0 || ( arr.order !== 'row-major' && arr.order !== 'column-major' ) ) {
			return false;
		}
		data = getData( arr );
		if ( i === 0 ) {
			if ( getDType( arr ) !== 'bool' || !isBooleanArray( data ) ) {
				return false;
			}
		} else if ( getDType( arr ) !== 'float64' || !isFloat64Array( data ) ) {
			return false;
		}
		stride = getStride( arr, 0 );
		offset = getOffset( arr );
		last = offset + ( ( N-1 ) * stride );
		if ( !isSafeInteger( stride ) || !isSafeInteger( offset ) || !isSafeInteger( last ) || offset < 0 || offset >= data.length || last < 0 || last >= data.length ) {
			return false;
		}
	}
	return true;
}


// EXPORTS //

module.exports = canUseNative;
